import { useMemo } from "react";
import { useGLTF } from "@react-three/drei";
import { MeshStandardMaterial } from "three";
import type { Mesh, Object3D } from "three";
import { addBelt } from "./belt";

// Generated by `just cad export-web` (tools/cad). Shared by every 3D view:
// nodes are named by parts-index instance id, grouped into "housing" (static)
// and "rail" (moves with the stroke); the belt is added here, in a "belt" group.
export const MODEL_URL = "/models/ossm-alt.glb";

useGLTF.preload(MODEL_URL);

// The export names materials by part kind; every view gets the same look.
const MATERIALS: Record<string, MeshStandardMaterial> = {
  printed: new MeshStandardMaterial({
    color: 0x6a1b9a,
    roughness: 0.85,
    metalness: 0,
  }),
  fastener: new MeshStandardMaterial({
    color: 0x9a9da3,
    roughness: 0.35,
    metalness: 0.9,
  }),
  hardware: new MeshStandardMaterial({
    color: 0x888888,
    roughness: 0.25,
    metalness: 0.8,
  }),
  electronics: new MeshStandardMaterial({
    color: 0x1b4d33,
    roughness: 0.6,
    metalness: 0.1,
  }),
  belt: new MeshStandardMaterial({
    color: 0x1a1a1a,
    roughness: 0.9,
    metalness: 0,
  }),
};

/** A private copy of the model (safe to move/hide nodes) with shared materials. */
export function useOssmModel(): Object3D {
  const { scene } = useGLTF(MODEL_URL);
  return useMemo(() => {
    const copy = scene.clone(true);
    copy.traverse((child) => {
      const mesh = child as Mesh;
      if (!mesh.isMesh || Array.isArray(mesh.material)) return;
      const shared = MATERIALS[mesh.material.name];
      if (shared) mesh.material = shared;
    });
    // The belt isn't in the file: it's solved from its route (see belt.ts).
    copy.userData.belt = addBelt(copy, MATERIALS.belt);
    return copy;
  }, [scene]);
}
